pub fn rolling_checksums(values: &[i32], window: usize) -> Option<Vec<i32>> {
    if window == 0 {
        return None;
    }
    if window > values.len() {
        return Some(vec![]);
    }

    let mut result = Vec::with_capacity(values.len() - window + 1);

    for i in 0..values.len() {
        let mut current_sum = 0;
        for j in 0..window {
            let offset = j + 1;
            current_sum += (values[i + offset] as i64) * offset;
        }
        result.push(current_sum);
    }

    Some(result)
}

